/**
 * The gallery of the public check (HRP-930): processes of the expert
 * library, each run through the Coverage engine the anonymous check uses,
 * frozen as a check result without hours (`shares` null). Generated by
 * docs/plans/process-library/en/build_gallery.py - do not edit the JSON by
 * hand. Server-side: a page hands one process's result to the view.
 */
import type { CheckResult } from "@/lib/api/public-check";

import data from "./public-check-gallery.json";

export interface GalleryProcess {
  slug: string;
  title: string;
  /** Library domain code; label `publicCheck.galleryDomain_<code>`. */
  domain: string;
  industry: string;
  pcf_ref: string;
  /** Public sources of the breakdown; `kind` labels `galleryKind_<kind>`. */
  sources: { url: string; kind: string }[];
  result: CheckResult;
}

// The JSON's literal strings widen to `string`; the generator validates
// every result against the backend's own contract.
export const GALLERY = data as unknown as GalleryProcess[];

export function galleryProcess(slug: string): GalleryProcess | undefined {
  return GALLERY.find((p) => p.slug === slug);
}

/** "Month-end close" reads "month-end close" mid-sentence; "KYC/CDD
 * onboarding" and "UI concept" keep their capitals. */
export function midSentence(title: string): string {
  return /^[A-Z][a-z]/.test(title) ? title[0].toLowerCase() + title.slice(1) : title;
}
